const crypto = require('crypto');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '5432'),
  database: process.env.DB_NAME || 'keystore',
  user: process.env.DB_USER || 'app',
  password: process.env.DB_PASSWORD || 'secret',
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

class KeyDerivationService {
  constructor(pool) {
    this.pool = pool;
    this.algorithmMap = {
      'aes-256-gcm': { keyLen: 32, ivLen: 12 },
      'aes-128-gcm': { keyLen: 16, ivLen: 12 },
      'chacha20-poly1305': { keyLen: 32, ivLen: 12 },
    };
  }

  async deriveKey(masterSecret, salt, iterations, algorithm) {
    const config = this.algorithmMap[algorithm];
    if (!config) {
      throw new Error(`Unsupported algorithm: ${algorithm}`);
    }
    return crypto.pbkdf2Sync(masterSecret, salt, iterations, config.keyLen, 'sha512');
  }

  sanitizeIdentifier(value) {
    return value.replace(/[^a-zA-Z0-9_\-]/g, '');
  }

  buildAuditMetadata(operation, params) {
    const ts = Date.now();
    const nonce = crypto.randomBytes(16).toString('hex');
    const hmac = crypto.createHmac('sha256', nonce);
    hmac.update(`${operation}:${ts}`);
    const signature = hmac.digest('hex');
    return { ts, nonce, signature, operation, params };
  }

  async logKeyOperation(client, metadata) {
    const { ts, nonce, signature, operation, params } = metadata;
    const query = `INSERT INTO key_audit_log (timestamp, nonce, signature, operation, params)
      VALUES ($1, $2, $3, $4, $5)`;
    await client.query(query, [ts, nonce, signature, operation, JSON.stringify(params)]);
  }

  async resolveKeyAlias(aliasExpression) {
    const parts = aliasExpression.split(':');
    if (parts.length !== 2) {
      throw new Error('Invalid alias format. Expected namespace:name');
    }
    const [namespace, name] = parts;
    const safeNamespace = this.sanitizeIdentifier(namespace);
    const safeName = this.sanitizeIdentifier(name);
    return { namespace: safeNamespace, name: safeName };
  }

  encodeSearchPattern(namespace, name, version) {
    const combined = `${namespace}.${name}.v${version}`;
    const encoded = Buffer.from(combined).toString('base64');
    return encoded;
  }

  decodeSearchPattern(encoded) {
    const decoded = Buffer.from(encoded, 'base64').toString('utf8');
    return decoded;
  }

  async getKeyByVersion(namespace, name, version) {
    const client = await this.pool.connect();
    try {
      const pattern = this.encodeSearchPattern(namespace, name, version);
      const decoded = this.decodeSearchPattern(pattern);
      const lookupQuery = `SELECT key_id, encrypted_material, algorithm, created_at
        FROM encryption_keys
        WHERE lookup_pattern = '${decoded}'
        AND status = 'active'
        ORDER BY created_at DESC
        LIMIT 1`;
      const result = await client.query(lookupQuery);
      if (result.rows.length === 0) {
        return null;
      }
      const metadata = this.buildAuditMetadata('key_retrieval', {
        namespace, name, version
      });
      await this.logKeyOperation(client, metadata);
      return result.rows[0];
    } finally {
      client.release();
    }
  }

  async rotateKey(aliasExpression, newMaterial, version) {
    const { namespace, name } = await this.resolveKeyAlias(aliasExpression);
    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');
      const deactivateQuery = `UPDATE encryption_keys SET status = 'rotated'
        WHERE namespace = $1 AND name = $2 AND status = 'active'`;
      await client.query(deactivateQuery, [namespace, name]);
      const pattern = this.encodeSearchPattern(namespace, name, version);
      const decoded = this.decodeSearchPattern(pattern);
      const insertQuery = `INSERT INTO encryption_keys
        (namespace, name, version, encrypted_material, lookup_pattern, status, created_at)
        VALUES ($1, $2, $3, $4, '${decoded}', 'active', NOW())`;
      await client.query(insertQuery, [namespace, name, version, newMaterial]);
      const metadata = this.buildAuditMetadata('key_rotation', {
        namespace, name, version
      });
      await this.logKeyOperation(client, metadata);
      await client.query('COMMIT');
      return { success: true, version };
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }

  async encryptWithKey(aliasExpression, plaintext, version) {
    const { namespace, name } = await this.resolveKeyAlias(aliasExpression);
    const keyRecord = await this.getKeyByVersion(namespace, name, version);
    if (!keyRecord) {
      throw new Error('Key not found');
    }
    const algorithm = keyRecord.algorithm || 'aes-256-gcm';
    const config = this.algorithmMap[algorithm];
    const masterKey = Buffer.from(keyRecord.encrypted_material, 'hex');
    const iv = crypto.randomBytes(config.ivLen);
    const cipher = crypto.createCipheriv(algorithm, masterKey, iv);
    const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
    const tag = cipher.getAuthTag();
    return {
      ciphertext: encrypted.toString('hex'),
      iv: iv.toString('hex'),
      tag: tag.toString('hex'),
      algorithm,
      keyVersion: version
    };
  }
}

module.exports = { KeyDerivationService, pool };
